dev:remarks.maml:para:
This example tells the Data Governance Server to update the agent state
for an agent identified by the agent id :
0ED27B0F-BCCD-448F-BCC6-BD7EFFBF7997.

command:example.dev:code:
$resources = Get-Content 'C:\Resources.txt'

foreach($resource in $resources)
{
   try
   {
      $governed = Get-QDataUnderGovernance $resource
      if($governed)
      {
         $perceivedOwner = Get-QPerceivedOwnerPoI $governed.UID_QAMDuG
         $resource += ';'
         $resource += $perceivedOwner.EmployeeId
         Add-Content 'c:\PerceivedOwnerResource.txt' $resource
      }
      else
      {
         $resource += ';'
         $resource += 'Resource Not Governed'
         Add-Content 'c:\PerceivedOwnerResource.txt' $resource
      }
   }
   catch
   {
      Writestatus $_
   }
					}
